recipe('cheesy-chorizo-arancini','Chorizo and mozzarella arancini',Q,4,200,30,45,[[180,'dry Arborio rice','F007682'],[60,'chorizo','F008126','Finely diced'],(60,'onion','Finely diced'),(5,'garlic','Grated'),(10,'oil'),(10,'butter'),(50,'mozz','Twelve small cubes'),[30,'parmesan','F002479','Grated'],(50,'egg','Beaten'),(30,'flour'),(60,'crumbs'),[2,'sage','F010439','Chopped'] ],['Soften onion and chorizo in a saucepan with butter and half the oil for 4 minutes. Add garlic and rice. Stir in 600 ml hot water gradually, simmering and stirring for about 20 minutes until rice is tender and the mixture thick. Stir in parmesan and sage.','Spread the rice thinly in a shallow container and refrigerate promptly for 1 hour. Shape into twelve balls around mozzarella cubes, fully enclosing the cheese.','Coat balls in flour, egg and breadcrumbs. Brush with remaining oil. Air fry in two single-layer batches at 200°C for 10–12 minutes each, turning after 7 minutes, until golden and 75°C inside.'],'Crumbed risotto balls enclose mozzarella and small pieces of smoky chorizo.',wait=60,internal=75,allergens=['wheat','gluten','milk','egg','sulphites'],difficulty='Moderate',equipment=['Saucepan','Shallow cooling container'],nutritionNote='Stovetop risotto replaces pressure cooking; stock replaced with water, sun-dried tomato dip omitted. Exact rice, coating and cheese weights counted. Cook time includes risotto and two air-fryer batches.',safety=['Cool rice promptly in a shallow container and refrigerate below 5°C; do not leave it on the bench to cool for an hour.'])
recipe('coconut-lime-cod-cauliflower-rice','Coconut fish with cauliflower rice',S,2,190,15,30,[[320,'hoki fillets','F001277','Two 160 g boneless fillets'],[100,'regular coconut milk','F002991'],(20,'lemon'),[350,'cauliflower','F002378','Grate into rice-sized pieces'],(70,'capsicum','Finely diced'),(50,'onion','Finely diced'),(5,'garlic','Grated'),(10,'oil'),[30,'roasted cashews','F006092','Chopped']],[ 'Coat fish with coconut milk and lemon, cover and refrigerate for 20 minutes.','Mix onion, garlic, capsicum and cauliflower with oil in a shallow approved dish. Air fry at 160°C for 12–15 minutes, stirring twice, until vegetables are tender. Keep warm.','Lift fish from marinade and discard excess marinade. Air fry fish at 190°C for 12–15 minutes until its thickest point reaches 63°C. Serve over the cauliflower with cashews.'],'Coconut-marinated fish rests on finely chopped cauliflower with roasted cashew crunch.',wait=20,internal=63,allergens=['fish','tree-nut'],equipment=['Shallow air-fryer-safe dish'],nutritionNote='Hoki replaces cod and lemon replaces lime. All 100 g coconut marinade counted although unused marinade is discarded. Single-basket timing includes vegetable and fish stages.')
recipe('haddock-croquettes','Hoki and parsley croquettes',S,4,200,25,17,[[500,'hoki fillets','F001277','Boneless, minced finely'],(50,'crumbs','For mixture'),(100,'egg','Half in mixture, half for coating'),(15,'parsley','Chopped'),(15,'lemon'),(40,'flour'),(60,'crumbs','For coating'),(10,'oil'),[2,'ground coriander','F003190']],[ 'Mix minced raw fish with 50 g breadcrumbs, half the beaten egg, parsley, lemon and coriander. Refrigerate for 15 minutes to firm.','With lightly floured hands, shape twelve small croquettes, about 5 cm long and 2 cm thick. Coat with remaining flour, egg and breadcrumbs and brush with oil.','Air fry in one layer at 200°C for 14–17 minutes, turning after 8 minutes. Check centres reach 75°C because the mixture contains raw fish and egg.'],'These small parsley-flecked fish croquettes use breadcrumbs for structure and a crisp coating.',wait=15,internal=75,allergens=['fish','egg','wheat','gluten'],nutritionNote='Hoki replaces haddock; lemon juice replaces sherry. All measured coating counted. Unlike potato fishcakes, this mixture is bound with breadcrumbs and egg.')
recipe('garlic-prawns-blistered-rosemary-tomatoes-recipe','Garlic prawns with blistered tomatoes',S,2,200,10,23,[(350,'prawn','Peeled, deveined and dry'),[300,'cherry tomatoes','F009190'],(10,'garlic','Finely chopped'),(15,'oil','10 g prawns; 5 g tomatoes'),[3,'fresh thyme','F010466','Leaves only'],[1,'dried rosemary','F007715'],(1,'chilli')],[ 'Toss tomatoes with 5 g oil and rosemary. Air fry in a shallow dish at 200°C for 10 minutes, shaking after 5 minutes.','Toss prawns with garlic, thyme, chilli and remaining oil. Cook in one layer at 200°C for 8–13 minutes, turning halfway, until 63°C in the thickest prawn.','Spoon tomatoes and their hot juices over the prawns and serve immediately.'],'Roasted cherry tomatoes release a quick sauce around garlic and thyme prawns.',internal=63,allergens=['crustacean'],equipment=['Shallow air-fryer-safe dish'],nutritionNote='Oil reduced to a measured 15 g total; source dual-zone method converted to sequential single-basket timing.')
recipe('salami-ricotta-calzone-recipe','Salami and ricotta calzones',Q,2,220,20,10,[[300,'ready-to-roll pizza dough','F001653','Commercial pizza-base nutrient proxy'],[100,'ricotta','F002488'],(70,'mozz','Diced'),[40,'salami','F007818','Thinly sliced'],(80,'tomato','Crushed','canned'),(20,'paste'),[5,'basil','F000396','Torn'],(5,'oil')],[ 'Divide dough into two balls and roll into circles about 22 cm across. Mix tomato and paste. Spread ricotta, half the tomato mixture, mozzarella, salami and basil over one half of each circle, leaving a 2 cm border.','Moisten the borders with water, fold into half-moons and press and crimp firmly to seal. Brush with oil and remaining tomato sauce.','Air fry at 220°C for 8–10 minutes, checking after 8 minutes to prevent burning. Continue in short intervals until inner dough is baked and filling reaches 75°C. If the appliance only reaches 200°C, cook for 12–15 minutes and check again.'],'Half-moon pizza pockets combine ricotta, mozzarella and salami beneath a tomato-brushed crust.',internal=75,allergens=['wheat','gluten','milk'],nutritionNote='AFCD commercial pizza base is a declared proxy for raw dough. Two calzones require separate batches in a small basket; extra batch time is additional.',safety=['Use 220°C only if supported by the appliance; the 200°C alternative requires a longer check.'])
recipe('spicy-italian-sausage-capsicum-mushroom-onion-subs-recipe','Sausage, mushroom and capsicum rolls',Q,2,195,15,30,[(240,'sausage','Four small sausages'),(150,'capsicum','Thinly sliced'),(100,'mushroom','Sliced'),(80,'onion','Thinly sliced'),(10,'oil'),(140,'bread','Two 70 g rolls'),(15,'mustard')],[ 'Toss capsicum, mushrooms and onion with oil. Air fry at 195°C for 10 minutes, stirring halfway.','Add sausages with space around them and air fry for another 15–20 minutes, turning sausages and stirring vegetables twice. Sausage centres must reach 71°C.','Split rolls and spread with mustard. Fill with sausages and the soft browned vegetables.'],'Sausages and browned mushrooms fill bread rolls with sweet capsicum, onion and mustard.',internal=71,allergens=['wheat','gluten','sulphites'],nutritionNote='Measured beef sausages replace unspecified Italian links so that a raw AFCD nutrient reference can be used.')
recipe('fried-chicken','Buttermilk-style crumbed chicken pieces',C,4,180,20,40,[[800,'boneless skin-on chicken thigh','F002809','Four large pieces, about 200 g each'],(120,'yoghurt'),(60,'milk'),[30,'cornflour','F003988'],(100,'crumbs'),(5,'garlic','Grated'),(3,'paprika'),(1,'chilli'),(2,'thyme'),(10,'oil')],[ 'Mix yoghurt and milk with garlic, paprika, chilli and thyme. Coat chicken in the mixture.','Combine cornflour and breadcrumbs. Press the chicken into the coating, then brush with oil. Arrange skin-side up in a single layer.','Air fry at 180°C for 20 minutes, turn carefully and cook for 12–20 minutes more until the thickest piece reaches 74°C and the coating is crisp.'], 'A tangy yoghurt-and-milk coating holds crisp crumbs on large skin-on chicken pieces.',internal=74,allergens=['milk','wheat','gluten'],nutritionNote='Boneless thighs give explicit edible weights, replacing mixed bone-in pieces. Yoghurt and milk form a declared buttermilk substitute. Smoke flavour and all wood pellets are omitted for basket appliances. All coating counted.')
recipe('chicken-satay-with-peanut-sauce','Chicken satay with peanut dipping sauce',C,2,180,15,18,[(400,'chicken','Cut into long 2 cm strips'),(10,'oil'),(20,'soy','Half for marinade, half for sauce'),(5,'garlic','Grated'),(5,'ginger','Grated'),(1,'chilli'),(20,'lemon'),[50,'unsweetened peanut butter','F006579'],[35,'coconut cream','F002982'],(10,'honey'),[2,'curry powder','F003337']],[ 'Mix chicken with oil, half the soy sauce, garlic, ginger, chilli and half the lemon. Cover and refrigerate for 1 hour.','Mix peanut butter, coconut cream, honey, curry powder, remaining soy and lemon into a smooth sauce; add a little water if needed. Keep separate from raw chicken.','Air fry chicken in one layer at 180°C for 14–18 minutes, turning after 10 minutes, until 75°C in the thickest strip. Serve with the clean peanut sauce.'],'Marinated chicken strips pair with a thick peanut and coconut sauce for dipping.',wait=60,internal=75,allergens=['peanut','soy','wheat','gluten'],nutritionNote='Source CRISPi air-fry mode gives no adjustable temperature; 180°C is a basket adaptation with a 75°C thermometer endpoint. Lemon and honey replace lime and maple syrup; fish sauce and optional peanut garnish omitted.',safety=['This is an adaptation from a fixed-mode CRISPi appliance; basket times vary. Use the thermometer target, not the timer alone.'])
